import json
import shutil
from pathlib import Path

import pytest

from tools import import_asd_ism, import_mscp
from tools.file_references import is_binary_payload
from tools.source_lock import read_source_lock
from tools.validate_library import validate_library

REPO_ROOT = Path(__file__).resolve().parent.parent
BASELINES_DIR = REPO_ROOT / "baselines"
MSCP_SOURCES_DIR = REPO_ROOT / "sources" / "mscp"
ASD_ISM_SOURCES_DIR = REPO_ROOT / "sources" / "asd_ism"

# Maintainer-written, never generated by an importer.
OVERLAYS_DIR_NAME = "_overlays"

SOURCES = (
    pytest.param("mscp", MSCP_SOURCES_DIR, import_mscp.generate_library, id="mscp"),
    pytest.param("asd_ism", ASD_ISM_SOURCES_DIR, import_asd_ism.generate_library, id="asd_ism"),
)


def generated_files(baselines_dir: Path) -> dict[str, bytes]:
    paths = [baselines_dir / "_manifest.json"]
    for source_dir in baselines_dir.iterdir():
        if source_dir.is_dir() and source_dir.name != OVERLAYS_DIR_NAME:
            paths.extend(source_dir.rglob("*"))
    return {
        path.relative_to(baselines_dir).as_posix(): path.read_bytes()
        for path in sorted(paths)
        if path.is_file()
    }


def committed_asd_ism_rules() -> list[dict]:
    rule_paths = sorted((BASELINES_DIR / "asd_ism" / "rules").glob("*.json"))
    return [json.loads(path.read_text(encoding="utf-8")) for path in rule_paths]


def test_committed_library_is_valid():
    assert validate_library(BASELINES_DIR) == []


@pytest.mark.parametrize(("source_name", "sources_dir", "generate_library"), SOURCES)
def test_committed_library_matches_regeneration(
    tmp_path, source_name, sources_dir, generate_library
):
    regenerated_dir = tmp_path / "baselines"
    shutil.copytree(BASELINES_DIR, regenerated_dir)

    generate_library(
        sources_dir / "upstream",
        read_source_lock(sources_dir / "source.json"),
        regenerated_dir,
    )

    committed = generated_files(BASELINES_DIR)
    regenerated = generated_files(regenerated_dir)
    assert regenerated.keys() == committed.keys()
    differing = [name for name in committed if committed[name] != regenerated[name]]
    assert differing == []


def test_every_manifest_source_is_regenerated_by_this_suite():
    manifest = json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))
    assert sorted(source["name"] for source in manifest["sources"]) == sorted(
        parameter.values[0] for parameter in SOURCES
    )


def test_committed_library_has_lf_line_endings_only():
    carriage_return_files = [
        path.relative_to(BASELINES_DIR).as_posix()
        for path in BASELINES_DIR.rglob("*")
        if path.is_file() and not is_binary_payload(path.name) and b"\r" in path.read_bytes()
    ]
    assert carriage_return_files == []


def test_binary_payload_types_are_marked_binary_for_git():
    attributes = (REPO_ROOT / ".gitattributes").read_text(encoding="utf-8").splitlines()
    text_rule = attributes.index("baselines/** text eol=lf")
    for extension in ("pol", "intunewin"):
        binary_rule = attributes.index(f"baselines/**/*.{extension} binary")
        assert binary_rule > text_rule, "a later .gitattributes line wins, so the binary rule must follow the text rule"


def test_vendored_license_present():
    license_text = (MSCP_SOURCES_DIR / "upstream" / "LICENSE.md").read_text(encoding="utf-8")
    assert "CC BY 4.0" in license_text


def test_asd_ism_vendored_license_present():
    readme_text = (ASD_ISM_SOURCES_DIR / "upstream" / "README.md").read_text(encoding="utf-8")
    assert "Creative Commons Attribution 4.0" in readme_text


def test_asd_ism_titles_and_discussions_have_no_unresolved_links():
    rules = committed_asd_ism_rules()
    assert rules
    unresolved = [
        rule["id"] for rule in rules if "](#" in rule["discussion"] or "](#" in rule["title"]
    ]
    assert unresolved == []


def test_asd_ism_titles_are_single_paragraphs():
    rules = committed_asd_ism_rules()
    assert rules
    multi_paragraph_titles = [rule["id"] for rule in rules if "\n\n" in rule["title"]]
    assert multi_paragraph_titles == []


def test_asd_ism_multi_paragraph_statement_keeps_its_full_text_before_the_overview():
    incident_register = json.loads(
        (BASELINES_DIR / "asd_ism" / "rules" / "ism-1803.json").read_text(encoding="utf-8")
    )
    discussion = incident_register["discussion"]

    assert discussion.startswith(
        "A cyber security incident register contains the following for each cyber security incident:"
    )
    assert "- to whom the cyber security incident was reported." in discussion
    statement_end = discussion.index("- to whom the cyber security incident was reported.")
    statement_end += len("- to whom the cyber security incident was reported.")
    assert discussion[statement_end:].startswith("\n\nDeveloping, implementing and maintaining")


def test_asd_ism_multi_paragraph_statements_in_this_release_number_forty():
    rules = committed_asd_ism_rules()
    multi_paragraph_rules = [
        rule["id"] for rule in rules if rule["discussion"].startswith(rule["title"] + "\n\n")
    ]
    assert len(multi_paragraph_rules) == 40


def test_overlays_folder_is_not_a_source_and_keeps_lf_endings():
    manifest = json.loads((BASELINES_DIR / "_manifest.json").read_text(encoding="utf-8"))
    assert OVERLAYS_DIR_NAME not in [source["name"] for source in manifest["sources"]]
    overlay_paths = sorted((BASELINES_DIR / OVERLAYS_DIR_NAME / "rules").glob("*.json"))
    assert overlay_paths
    assert [path.name for path in overlay_paths if b"\r" in path.read_bytes()] == []
